CREATE TABLE loading_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('LOAD-'||gen_random_uuid()::text),project_id uuid NOT NULL REFERENCES projects(id),customer_id uuid NOT NULL REFERENCES customers(id),vehicle_no text NOT NULL CHECK(length(trim(vehicle_no)) BETWEEN 1 AND 80),carrier text NOT NULL CHECK(length(trim(carrier)) BETWEEN 1 AND 160),loading_point text NOT NULL CHECK(length(trim(loading_point)) BETWEEN 1 AND 160),loaded_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','LOADED','CANCELLED','DEPARTED','REVERSED')),created_by uuid NOT NULL REFERENCES users(id),completed_by uuid REFERENCES users(id),completed_at timestamptz,cancel_reason text,cancelled_by uuid REFERENCES users(id),cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id));
CREATE UNIQUE INDEX one_active_vehicle ON loading_orders(vehicle_no) WHERE status IN('DRAFT','LOADED');
CREATE TABLE loading_items(loading_id uuid NOT NULL REFERENCES loading_orders(id),bundle_id uuid NOT NULL REFERENCES bundles(id),reservation_id uuid NOT NULL REFERENCES reservations(id),original_weight numeric(14,6) NOT NULL CHECK(original_weight>0),original_location_id uuid NOT NULL REFERENCES locations(id),active boolean NOT NULL DEFAULT true,removed_reason text,removed_at timestamptz,PRIMARY KEY(loading_id,bundle_id));
CREATE UNIQUE INDEX one_active_vehicle_bundle ON loading_items(bundle_id) WHERE active;
CREATE TRIGGER loading_state BEFORE UPDATE OR DELETE ON loading_orders FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE FUNCTION loading_item_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE d loading_orders;b bundles;r reservations;customer uuid;w uuid;BEGIN
 IF TG_OP='DELETE' OR(TG_OP='UPDATE' AND current_user<>'musonoi_owner') THEN RAISE EXCEPTION 'Loading history immutable' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' THEN IF NOT OLD.active OR NEW.active OR(to_jsonb(NEW)-ARRAY['active','removed_reason','removed_at'])<>(to_jsonb(OLD)-ARRAY['active','removed_reason','removed_at']) OR length(trim(NEW.removed_reason))<1 THEN RAISE EXCEPTION 'Only authorized unloading allowed' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 SELECT * INTO d FROM loading_orders WHERE id=NEW.loading_id FOR UPDATE;SELECT * INTO b FROM bundles WHERE id=NEW.bundle_id FOR UPDATE;SELECT * INTO r FROM reservations WHERE id=NEW.reservation_id FOR UPDATE;SELECT p.customer_id INTO customer FROM allocations a JOIN sales_plans p ON p.id=a.plan_id WHERE a.id=r.allocation_id;
 SELECT warehouse_id INTO w FROM locations WHERE id=b.location_id;PERFORM v23_require(d.created_by,'load:write',d.project_id,d.customer_id,w);
 IF d.status<>'DRAFT' OR b.physical_status<>'IN_STOCK' OR b.project_id<>d.project_id OR r.bundle_id<>b.id OR r.released_at IS NOT NULL OR customer<>d.customer_id OR NEW.original_weight<>b.net_weight OR NEW.original_location_id<>b.location_id OR NOT NEW.active THEN RAISE EXCEPTION 'Load requires exact active customer reservation' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER loading_item_rules BEFORE INSERT OR UPDATE OR DELETE ON loading_items FOR EACH ROW EXECUTE FUNCTION loading_item_guard();
CREATE FUNCTION reservation_loaded_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.released_at IS NULL AND NEW.released_at IS NOT NULL AND current_user<>'musonoi_owner' AND EXISTS(SELECT 1 FROM loading_items WHERE reservation_id=OLD.id AND active) THEN RAISE EXCEPTION 'Unload or cancel shipment before releasing customer reservation' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER reservation_loaded BEFORE UPDATE ON reservations FOR EACH ROW EXECUTE FUNCTION reservation_loaded_guard();
ALTER TABLE weighings ADD FOREIGN KEY(loading_id) REFERENCES loading_orders(id);
CREATE FUNCTION weighing_load_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE d loading_orders;BEGIN IF NEW.loading_id IS NOT NULL THEN SELECT * INTO d FROM loading_orders WHERE id=NEW.loading_id FOR UPDATE;IF d.status<>'LOADED' OR NEW.project_id<>d.project_id OR NEW.customer_id<>d.customer_id OR NEW.vehicle_no<>d.vehicle_no OR NEW.kind<>'VEHICLE' THEN RAISE EXCEPTION 'Vehicle weighing must match a completed loading order' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER weighing_load BEFORE INSERT ON weighings FOR EACH ROW EXECUTE FUNCTION weighing_load_guard();
CREATE FUNCTION loading_action(actor uuid,doc uuid,expected int,action text,reason text DEFAULT '') RETURNS loading_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d loading_orders;i loading_items;b bundles;w uuid;BEGIN
 SELECT * INTO d FROM loading_orders WHERE id=doc FOR UPDATE;
 IF NOT FOUND OR d.version<>expected OR NOT((action='complete' AND d.status='DRAFT') OR(action IN('cancel','unload') AND d.status IN('DRAFT','LOADED') AND length(trim(reason)) BETWEEN 1 AND 500)) THEN RAISE EXCEPTION 'Loading state or version conflict' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM loading_items WHERE loading_id=doc AND active) THEN RAISE EXCEPTION 'Loading has no active bundles' USING ERRCODE='23514';END IF;
 FOR i IN SELECT * FROM loading_items WHERE loading_id=doc AND active ORDER BY bundle_id LOOP
 SELECT * INTO b FROM bundles WHERE id=i.bundle_id FOR UPDATE;SELECT warehouse_id INTO w FROM locations WHERE id=b.location_id;PERFORM v23_require(actor,'load:write',d.project_id,d.customer_id,w);
 IF b.physical_status<>'IN_STOCK' OR NOT EXISTS(SELECT 1 FROM reservations WHERE id=i.reservation_id AND released_at IS NULL) THEN RAISE EXCEPTION 'Loading reservation changed' USING ERRCODE='23514';END IF;
 INSERT INTO inventory_events(bundle_id,event_type,physical_delta,actor_id,after_data) VALUES(b.id,CASE WHEN action='complete' THEN 'LOAD' ELSE 'UNLOAD' END,0,actor,jsonb_build_object('loading_id',doc,'code',d.code,'vehicle_no',d.vehicle_no,'action',action,'reason',reason));END LOOP;
 IF action<>'complete' THEN UPDATE loading_items SET active=false,removed_reason=reason,removed_at=now() WHERE loading_id=doc AND active;END IF;
 UPDATE loading_orders SET status=CASE WHEN action='complete' THEN 'LOADED' ELSE 'CANCELLED' END,completed_by=CASE WHEN action='complete' THEN actor ELSE completed_by END,completed_at=CASE WHEN action='complete' THEN now() ELSE completed_at END,cancel_reason=CASE WHEN action<>'complete' THEN reason ELSE NULL END,cancelled_by=CASE WHEN action<>'complete' THEN actor ELSE NULL END,cancelled_at=CASE WHEN action<>'complete' THEN now() ELSE NULL END,version=version+1 WHERE id=doc RETURNING * INTO d;
 INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'loading_'||action,'loading_orders',doc::text,to_jsonb(d));RETURN d;END $$;
REVOKE ALL ON FUNCTION loading_action(uuid,uuid,int,text,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION loading_action(uuid,uuid,int,text,text) TO musonoi_app;
GRANT SELECT,INSERT ON loading_orders,loading_items TO musonoi_app;
